// Carte des tournées (Leaflet + OpenStreetMap, sans clé).
// Modèle : { source, depot: {nom, lat, lng}, tournees: [{ camion, couleur, km, geometrie,
//            etapes: [{ rang, heure, action, chantier, lat, lng }] }] }

// Décode une polyline Google (précision 5), format renvoyé par OpenRouteService.
function decoderPolyline(texte) {
  const points = [];
  let index = 0, lat = 0, lng = 0;
  while (index < texte.length) {
    for (const axe of [0, 1]) {
      let resultat = 0, decalage = 0, octet;
      do {
        octet = texte.charCodeAt(index++) - 63;
        resultat |= (octet & 0x1f) << decalage;
        decalage += 5;
      } while (octet >= 0x20);
      const delta = resultat & 1 ? ~(resultat >> 1) : resultat >> 1;
      if (axe === 0) lat += delta; else lng += delta;
    }
    points.push([lat / 1e5, lng / 1e5]);
  }
  return points;
}

let carte = null;
let couche = null;

// Fonds de carte. Les tuiles OpenStreetMap sont refusées depuis un widget
// Appsmith (pas de Referer) : fond Plan IGN (Géoplateforme, libre et sans clé,
// usage commercial permis), puis CARTO si l'IGN ne répond pas.
const FONDS = [
  ["https://data.geopf.fr/wmts?SERVICE=WMTS&REQUEST=GetTile&VERSION=1.0.0&LAYER=GEOGRAPHICALGRIDSYSTEMS.PLANIGNV2" +
    "&STYLE=normal&TILEMATRIXSET=PM&FORMAT=image/png&TILEMATRIX={z}&TILEROW={y}&TILECOL={x}",
    { maxZoom: 19, attribution: "&copy; IGN Plan IGN" }],
  ["https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}.png",
    { maxZoom: 19, subdomains: "abcd", attribution: "&copy; OpenStreetMap &copy; CARTO" }],
];

function ajouterFond(i) {
  const [url, options] = FONDS[i];
  const fond = L.tileLayer(url, options).addTo(carte);
  let chargees = 0, erreurs = 0;
  fond.on("tileload", () => chargees++);
  fond.on("tileerror", () => {
    if (++erreurs === 3 && chargees === 0 && i + 1 < FONDS.length) {
      carte.removeLayer(fond);
      ajouterFond(i + 1);
    }
  });
}

function initialiser() {
  carte = L.map("carte", { zoomControl: true });
  ajouterFond(0);
  couche = L.layerGroup().addTo(carte);
  carte.setView([48.87, 2.35], 10);
}

function echapper(t) {
  return String(t ?? "").replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
}

function afficher(modele) {
  if (!carte) initialiser();
  couche.clearLayers();
  const tournees = (modele && modele.tournees) || [];
  document.getElementById("vide").style.display = tournees.length ? "none" : "flex";
  const legende = document.getElementById("legende");
  legende.style.display = tournees.length ? "block" : "none";
  if (!tournees.length) return;

  const limites = [];
  const depot = modele.depot;
  if (depot && depot.lat != null) {
    const p = [Number(depot.lat), Number(depot.lng)];
    limites.push(p);
    L.marker(p, { icon: L.divIcon({ className: "", html: '<div class="depot">D</div>', iconSize: [26, 26] }) })
      .bindTooltip(echapper(depot.nom || "Dépôt"))
      .addTo(couche);
  }

  tournees.forEach(t => {
    const arrets = t.etapes.filter(e => e.lat != null && e.lng != null);
    let trace = t.geometrie ? decoderPolyline(t.geometrie) : null;
    const pointille = !trace;
    if (!trace) {
      // Sans tracé routier (proposition hors ligne) : liaison directe entre les arrêts.
      trace = arrets.map(e => [Number(e.lat), Number(e.lng)]);
      if (depot && depot.lat != null) {
        const d = [Number(depot.lat), Number(depot.lng)];
        trace = [d, ...trace, d];
      }
    }
    L.polyline(trace, { color: t.couleur, weight: 4, opacity: 0.85, dashArray: pointille ? "6 6" : null })
      .bindTooltip(echapper(t.camion))
      .addTo(couche);
    trace.forEach(p => limites.push(p));

    arrets.forEach(e => {
      const p = [Number(e.lat), Number(e.lng)];
      const icone = L.divIcon({
        className: "",
        html: `<div class="arret" style="background:${t.couleur}">${e.rang}</div>`,
        iconSize: [22, 22],
      });
      L.marker(p, { icon: icone })
        .bindTooltip(`<b>${echapper(e.heure)}</b> · ${echapper(e.action)}<br>${echapper(e.chantier)}<br><i>${echapper(t.camion)}</i>`)
        .addTo(couche);
      limites.push(p);
    });
  });

  legende.innerHTML =
    `<div class="source">${modele.source === "proposition" ? "Proposition (non enregistrée)" : "Tournées enregistrées"}</div>` +
    tournees.map(t =>
      `<div class="ligne"><span class="pastille" style="background:${t.couleur}"></span>` +
      `${echapper(t.camion)} · ${t.etapes.length} arrêt(s)${t.km != null ? " · " + t.km + " km" : ""}</div>`
    ).join("");

  if (limites.length) carte.fitBounds(limites, { padding: [30, 30] });
}

appsmith.onReady(() => {
  afficher(appsmith.model);
  appsmith.onModelChange(modele => afficher(modele));
});

